import { useHiLight } from '@pixelkit-labs/sdk';

function StatusRing() {
  const hilight = useHiLight();
  return (
    <View>
      <Text>{hilight.availability} · {hilight.mode}</Text>
      <Button title="Thinking pulse" onPress={() => hilight.triggerGeminiPulse(4000)} />
    </View>
  );
}
